-- M74 additive source-scoped synthetic mobile-diesel workpapers. Earlier history remains intact.
create table neuvetra.mobile_diesel_heads(id uuid primary key,company_id uuid not null references neuvetra.companies(id),source_id uuid not null,asset_id text not null,vehicle_key text not null,version_id uuid,revision integer not null default 0,fuel_reference_key text,mileage_reference_key text,unique(id,company_id),unique(company_id,source_id),unique(company_id,vehicle_key));
create table neuvetra.mobile_diesel_fuel_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.mobile_diesel_mileage_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.mobile_diesel_evidence_reservations(company_id uuid not null references neuvetra.companies(id),evidence_key text not null,worksheet_id uuid not null,statement_kind text not null check(statement_kind in('fuel','mileage')),created_at timestamptz not null,primary key(company_id,evidence_key));
create table neuvetra.mobile_diesel_versions(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,fuel_statement_id uuid,mileage_statement_id uuid,quantity_gallons numeric(15,3),distance_miles numeric(15,3),payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,worksheet_id,version),foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id),foreign key(coverage_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id),foreign key(fuel_statement_id,company_id) references neuvetra.mobile_diesel_fuel_statements(id,company_id),foreign key(mileage_statement_id,company_id) references neuvetra.mobile_diesel_mileage_statements(id,company_id));
alter table neuvetra.mobile_diesel_heads add foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id);
alter table neuvetra.mobile_diesel_evidence_reservations add foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id);
create table neuvetra.mobile_diesel_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id));
create table neuvetra.mobile_diesel_reports(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version_id uuid not null,decision_id uuid,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id),foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id),foreign key(decision_id,company_id) references neuvetra.mobile_diesel_reviews(id,company_id));
create unique index m74_report_state on neuvetra.mobile_diesel_reports(company_id,version_id,coalesce(decision_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table neuvetra.mobile_diesel_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.mobile_diesel_audit(id uuid primary key,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
do $$declare t text;begin foreach t in array array['mobile_diesel_heads','mobile_diesel_fuel_statements','mobile_diesel_mileage_statements','mobile_diesel_evidence_reservations','mobile_diesel_versions','mobile_diesel_reviews','mobile_diesel_reports','mobile_diesel_requests','mobile_diesel_audit'] loop
execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m74_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);
if t<>'mobile_diesel_heads' then execute format('create trigger m74_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;
create function neuvetra.m74_text(v jsonb,maximum integer) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or length(s) not between 1 and maximum or s<>btrim(s) or s~U&'^[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]|[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]$' or s<>normalize(s,NFC) or s~'[[:cntrl:]]' then raise exception 'invalid text' using errcode='22023';end if;return s;end $$;
create function neuvetra.m74_quantity(v jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or s!~'^(0|[1-9][0-9]{0,11})\.[0-9]{3}$' then raise exception 'invalid quantity' using errcode='22023';end if;return s;end $$;
create function neuvetra.m74_exact(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when position('.' in v::text)>0 then rtrim(rtrim(v::text,'0'),'.') else v::text end$$;
create function neuvetra.m74_display(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with x as(select v*10000 n),r as(select trunc(n) q,n-trunc(n) f from x) select to_char((q+case when f>0.5 or(f=0.5 and mod(q,2)=1)then 1 else 0 end)/10000,'FM999999999999999999999990.0000') from r$$;
create function neuvetra.m74_activity_status(a jsonb) returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_object('fuel',case when a->'quantityGallons'='null' then 'missing' when a->'fuelStatement'='null' then 'evidence_missing' when a->'fuelManualConfirmation'<>'true' then 'unconfirmed' when a->>'quantityGallons'<>a#>>'{fuelStatement,statedQuantityGallons}' then 'discrepancy' when a->>'quantityGallons'='0.000' then 'explicit_zero' else 'entered' end,'mileage',case when a->'distanceMiles'='null' then 'missing' when a->'mileageStatement'='null' then 'evidence_missing' when a->'mileageManualConfirmation'<>'true' then 'unconfirmed' when a->>'distanceMiles'<>a#>>'{mileageStatement,statedDistanceMiles}' then 'discrepancy' when a->>'distanceMiles'='0.000' then 'explicit_zero' else 'entered' end)$$;
create function neuvetra.m74_can_calculate(a jsonb) returns boolean language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select a->'quantityGallons'<>'null' and a->'distanceMiles'<>'null' and a->'fuelStatement'<>'null' and a->'mileageStatement'<>'null' and a->'fuelManualConfirmation'='true' and a->'mileageManualConfirmation'='true' and (a->>'quantityGallons'=a#>>'{fuelStatement,statedQuantityGallons}' or a->'fuelDiscrepancyReason'<>'null') and (a->>'distanceMiles'=a#>>'{mileageStatement,statedDistanceMiles}' or a->'mileageDiscrepancyReason'<>'null') and ((a->>'quantityGallons'<>'0.000' and a->>'distanceMiles'<>'0.000') or (a->>'quantityGallons'='0.000' and a->>'distanceMiles'='0.000' and a#>>'{fuelStatement,statedQuantityGallons}'='0.000' and a#>>'{mileageStatement,statedDistanceMiles}'='0.000' and a->'zeroReason'<>'null'))$$;
create function neuvetra.m74_findings(a jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare out jsonb:='[{"code":"scope1_incomplete","message":"This vehicle mobile-combustion subtotal does not complete stationary, mobile, fugitive or process emissions."},{"code":"method_not_released","message":"Factors and method are development candidates; no reporting or assurance determination."}]';s jsonb:=neuvetra.m74_activity_status(a);begin
if a->'quantityGallons'='null' then out:=out||'[{"code":"fuel_activity_missing","message":"Consumed gallons are missing; no emissions were calculated."}]';end if;if a->'distanceMiles'='null' then out:=out||'[{"code":"mileage_activity_missing","message":"Vehicle-miles are missing; no emissions were calculated."}]';end if;if a->'fuelStatement'='null' then out:=out||'[{"code":"fuel_statement_missing","message":"No synthetic annual fuel statement is retained."}]';end if;if a->'mileageStatement'='null' then out:=out||'[{"code":"mileage_statement_missing","message":"No synthetic annual mileage statement is retained."}]';end if;if s->>'fuel'='unconfirmed' then out:=out||'[{"code":"fuel_statement_unconfirmed","message":"The synthetic fuel assumptions have not been manually confirmed."}]';end if;if s->>'mileage'='unconfirmed' then out:=out||'[{"code":"mileage_statement_unconfirmed","message":"The synthetic mileage assumptions have not been manually confirmed."}]';end if;if s->>'fuel'='discrepancy' then out:=out||'[{"code":"fuel_activity_statement_discrepancy","message":"Entered and stated consumed gallons differ; the discrepancy remains unresolved."}]';end if;if s->>'mileage'='discrepancy' then out:=out||'[{"code":"mileage_activity_statement_discrepancy","message":"Entered and stated vehicle-miles differ; the discrepancy remains unresolved."}]';end if;if a->'quantityGallons'<>'null' and a->'distanceMiles'<>'null' and ((a->>'quantityGallons'='0.000')<>(a->>'distanceMiles'='0.000')) then out:=out||'[{"code":"mixed_zero_contradiction","message":"Zero in only one activity dimension is outside this bounded method; no emissions were calculated."}]';end if;if a->>'quantityGallons'='0.000' and a->>'distanceMiles'='0.000' and not neuvetra.m74_can_calculate(a) then out:=out||'[{"code":"unsupported_zero","message":"Zero activity needs matching zero statements, both confirmations and a no-operation/no-consumption reason."}]';end if;return out;end $$;
create function neuvetra.m74_coverage(target_company uuid,b jsonb,current_required boolean default true) returns jsonb language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare cv record;s jsonb;e jsonb;f jsonb;src jsonb;bd jsonb;rel jsonb;node text;seen text[]:='{}';pair record;begin
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');for pair in select key,value from jsonb_each(b) loop if jsonb_typeof(pair.value)<>'string' or (pair.value#>>'{}') !~ (case when pair.key='coverageVersionSha256' then '^[0-9a-f]{64}$' else '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' end) then raise exception 'invalid binding' using errcode='22023';end if;end loop;
select * into cv from neuvetra.corporate_inventory_versions where company_id=target_company and id=(b->>'coverageVersionId')::uuid;if not found or cv.version_sha256<>b->>'coverageVersionSha256' then raise exception 'coverage binding conflict' using errcode='23505';end if;
if current_required and not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and version_id=cv.id) then raise exception 'coverage changed' using errcode='23505';end if;
s:=cv.payload->'snapshot';perform neuvetra.m71_snapshot(s,null);if neuvetra.m67_hash(s)<>cv.content_sha256 or neuvetra.m67_hash((cv.payload-'snapshot'-'versionSha256')||jsonb_build_object('profile','synthetic-corporate-coverage-v1'))<>cv.version_sha256 or cv.export_text<>neuvetra.m67_canonical(cv.payload||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null)) then raise exception 'coverage integrity failure' using errcode='22023';end if;
select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=b->>'entityId';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=b->>'facilityId';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=b->>'sourceId';select x into bd from jsonb_array_elements(s->'boundaryDecisions')x where x->>'id'=b->>'boundaryDecisionId';
if s->>'consolidationApproach'<>'operational_control' or e is null or f is null or src is null or bd is null or src->>'domain'<>'mobile_combustion' or src->>'entityId'<>e->>'id' or src->>'facilityId'<>f->>'id' or f->>'entityId'<>e->>'id' or bd->>'entityId'<>e->>'id' or e->>'countryCode'<>'US' or e->>'regionCode' is distinct from 'CA' or f->>'countryCode'<>'US' or f->>'regionCode' is distinct from 'CA' or bd->>'disposition'<>'included_activity' or bd->'reason'='null' or jsonb_array_length(bd->'evidenceRefs')=0 then raise exception 'source ineligible' using errcode='22023';end if;
for pair in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if pair.value->>'start'<>'2025-01-01' or pair.value->>'endExclusive'<>'2026-01-01' then raise exception 'unsupported period' using errcode='22023';end if;end loop;
node:=e->>'id';loop if node=any(seen) then raise exception 'relationship cycle' using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements(s->'relationships')x where x->>'childEntityId'=node;exit when rel is null;if rel->>'start'<>'2025-01-01' or rel->>'endExclusive'<>'2026-01-01' or rel->>'ownershipPercent' is distinct from '100' or rel->'controlFacts'='null' or jsonb_array_length(rel->'evidenceRefs')=0 then raise exception 'control basis incomplete' using errcode='22023';end if;node:=rel->>'parentEntityId';end loop;
return cv.export_text::jsonb;end $$;
create function neuvetra.m74_validate_request(r jsonb) returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare a jsonb;k text;begin
perform neuvetra.m71_keys(r,'profile,binding,period,vehicle,quantityGallons,distanceMiles,fuelStatement,mileageStatement,fuelManualConfirmation,mileageManualConfirmation,fuelDiscrepancyReason,mileageDiscrepancyReason,zeroReason,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
if r->>'profile' is distinct from 'synthetic-mobile-diesel-v1' or r->'period' is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or jsonb_typeof(r->'fuelManualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'mileageManualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'idempotencyKey') is distinct from 'string' or r->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid profile' using errcode='22023';end if;
a:=r->'vehicle';perform neuvetra.m71_keys(a,'assetId,vehicleClass,classificationBasis,modelYear,fuel,controlBasis');if jsonb_typeof(a->'assetId')<>'string' or a->>'assetId'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$' or a->>'vehicleClass'<>'Medium- and Heavy-Duty Vehicles' or jsonb_typeof(a->'modelYear')<>'number' or a->>'modelYear'!~'^(200[7-9]|201[0-9]|202[0-2])$' or a->>'fuel'<>'Fossil Diesel' or a->>'controlBasis'<>'owned_operational_control_full_year' then raise exception 'unsupported vehicle' using errcode='22023';end if;perform neuvetra.m74_text(a->'classificationBasis',500);
foreach k in array array['fuelDiscrepancyReason','mileageDiscrepancyReason','zeroReason','correctionReason']loop if r->k<>'null' then perform neuvetra.m74_text(r->k,500);end if;end loop;
if r->'expectedVersionId'='null' then if r->'expectedVersionSha256'<>'null' or r->'correctionReason'<>'null' then raise exception 'initial binding invalid' using errcode='22023';end if;else if jsonb_typeof(r->'expectedVersionId')<>'string' or r->>'expectedVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(r->'expectedVersionSha256')<>'string' or r->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or r->'correctionReason'='null' then raise exception 'correction binding invalid' using errcode='22023';end if;end if;
if r->'quantityGallons'<>'null' then perform neuvetra.m74_quantity(r->'quantityGallons');end if;if r->'distanceMiles'<>'null' then perform neuvetra.m74_quantity(r->'distanceMiles');end if;
if r->'fuelStatement'<>'null' then a:=r->'fuelStatement';perform neuvetra.m71_keys(a,'issuer,reference,statedQuantityGallons,description,consumptionBasis');perform neuvetra.m74_text(a->'issuer',120);perform neuvetra.m74_text(a->'reference',120);perform neuvetra.m74_quantity(a->'statedQuantityGallons');perform neuvetra.m74_text(a->'description',2000);if a->>'consumptionBasis'<>'dedicated_vehicle_consumed_no_adjustments' then raise exception 'fuel basis invalid' using errcode='22023';end if;end if;
if r->'mileageStatement'<>'null' then a:=r->'mileageStatement';perform neuvetra.m71_keys(a,'issuer,reference,statedDistanceMiles,description,distanceBasis');perform neuvetra.m74_text(a->'issuer',120);perform neuvetra.m74_text(a->'reference',120);perform neuvetra.m74_quantity(a->'statedDistanceMiles');perform neuvetra.m74_text(a->'description',2000);if a->>'distanceBasis'<>'dedicated_vehicle_annual_distance' then raise exception 'distance basis invalid' using errcode='22023';end if;end if;end $$;
create function neuvetra.m74_statement(a jsonb,coverage jsonb,kind text) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s jsonb:=coverage->'snapshot';e jsonb;f jsonb;src jsonb;body jsonb;begin select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=a#>>'{binding,entityId}';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=a#>>'{binding,facilityId}';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=a#>>'{binding,sourceId}';if kind='fuel' then body:=jsonb_build_object('profile','m74-synthetic-fuel-statement-v1','companyLabel',s->'companyLabel','entityLabel',e->'legalName','facilityLabel',f->'name','sourceLabel',src->'name','binding',a->'binding','period',a->'period','vehicle',a->'vehicle','quantityUnit','US_gallon','fuelComposition','fossil_diesel_only','statement',a->'fuelStatement');return 'SYNTHETIC — NOT A FUEL RECEIPT OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(body)||chr(10);elsif kind='mileage' then body:=jsonb_build_object('profile','m74-synthetic-mileage-statement-v1','companyLabel',s->'companyLabel','entityLabel',e->'legalName','facilityLabel',f->'name','sourceLabel',src->'name','binding',a->'binding','period',a->'period','vehicle',a->'vehicle','distanceUnit','vehicle_mile','tripCoverage','all_trip_locations_including_interstate','statement',a->'mileageStatement');return 'SYNTHETIC — NOT AN ODOMETER RECORD OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(body)||chr(10);else raise exception 'invalid statement kind' using errcode='22023';end if;end $$;

create function neuvetra.m74_method() returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '{"id":"mobile-diesel-combustion","version":"m74-development-v1","engineSha256":"1dc0bb7249d91e854004a8cadd34068be3fc03ecdd6e10b4cf297d375d7f52a6","sourceSha256":"43afb91d79b2ae765b3a447549d9e1021a144a407cec5eb804be9fcf69a668a7","factorSha256":"416931c40b347f1e22e9d4019ca1c28bd27ce40d7c16a3beeac3dadbbb783187","gwpSha256":"c151f9b90b23eba7ee9d36dd57a851ecf7a6f200c915579819b683d2b3b3c1c7","sourceTitle":"EPA GHG Emission Factors Hub 2025","sourceSheet":"Emission Factors Hub","factorCells":["C103:E103","C107:E107","C255:G256"],"gwpCells":["E523:E526"],"noteCells":["F3","F248:G248","C255:D256"],"co2KgPerGallon":"10.21","ch4GramsPerMile":"0.0095","n2oGramsPerMile":"0.0431","ch4Gwp":"28","n2oGwp":"265","gwpAssessment":"IPCC AR5 100-year","status":"development_candidate_not_released","releaseEligible":false,"rights":"unresolved_for_factor_release"}'::jsonb$$;
create function neuvetra.m74_calculation(a jsonb,fuel_hash text,mileage_hash text) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare gallons numeric;miles numeric;co2 numeric;ch4 numeric;n2o numeric;ch4e numeric;n2oe numeric;total numeric;i jsonb;body jsonb;begin
if not neuvetra.m74_can_calculate(a) then return 'null'::jsonb;end if;gallons:=(a->>'quantityGallons')::numeric;miles:=(a->>'distanceMiles')::numeric;co2:=gallons*10.21;ch4:=miles*0.0095/1000;n2o:=miles*0.0431/1000;ch4e:=ch4*28;n2oe:=n2o*265;total:=co2+ch4e+n2oe;
i:=jsonb_build_object('binding',a->'binding','period',a->'period','vehicle',a->'vehicle','quantityGallons',a->'quantityGallons','quantityUnit','US_gallon','distanceMiles',a->'distanceMiles','distanceUnit','vehicle_mile','fuelStatementSha256',fuel_hash,'mileageStatementSha256',mileage_hash);
body:=jsonb_build_object('profile','m74-decimal-result-v1','input',i,'inputSha256',neuvetra.m67_hash(i),'method',neuvetra.m74_method(),'gasResults',jsonb_build_object('co2',jsonb_build_object('mass',neuvetra.m74_exact(co2),'massUnit','kg CO2','co2e',neuvetra.m74_exact(co2),'co2eUnit','kg CO2e'),'ch4',jsonb_build_object('mass',neuvetra.m74_exact(ch4),'massUnit','kg CH4','co2e',neuvetra.m74_exact(ch4e),'co2eUnit','kg CO2e'),'n2o',jsonb_build_object('mass',neuvetra.m74_exact(n2o),'massUnit','kg N2O','co2e',neuvetra.m74_exact(n2oe),'co2eUnit','kg CO2e')),'total',jsonb_build_object('unrounded',neuvetra.m74_exact(total),'display',neuvetra.m74_display(total),'unit','kg CO2e','rounding','half_even_4dp'));
return body||jsonb_build_object('resultSha256',neuvetra.m67_hash(body));end $$;
create function neuvetra.m74_capacity(target_company uuid,new_bytes integer) returns void language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare used_bytes bigint;begin
select coalesce((select sum(octet_length(convert_to(export_text,'utf8'))+4096) from neuvetra.mobile_diesel_versions where company_id=target_company),0)+coalesce((select sum(octet_length(convert_to(payload::text,'utf8'))) from neuvetra.mobile_diesel_reports where company_id=target_company),0) into used_bytes;
if used_bytes+new_bytes>3800000 then raise exception 'history bytes limit' using errcode='54001';end if;end $$;
create function neuvetra.save_mobile_diesel(target_company uuid,target_worksheet uuid,request jsonb,calculation jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();head neuvetra.mobile_diesel_heads%rowtype;prior neuvetra.mobile_diesel_versions%rowtype;old neuvetra.mobile_diesel_requests%rowtype;reservation neuvetra.mobile_diesel_evidence_reservations%rowtype;coverage jsonb;a jsonb;fuel_statement jsonb:='null';mileage_statement jsonb:='null';fuel_id uuid;mileage_id uuid;fuel_text text;mileage_text text;fuel_hash text;mileage_hash text;fuel_key text;mileage_key text;vehicle_key text;expected_calc jsonb;body jsonb;v jsonb;contributors jsonb;fingerprint text;input_hash text;content_hash text;version_hash text;frozen text;new_id uuid:=gen_random_uuid();captured timestamptz;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;
perform neuvetra.m74_validate_request(request);fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.mobile_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
coverage:=neuvetra.m74_coverage(target_company,request->'binding',true);a:=request-'expectedVersionId'-'expectedVersionSha256'-'correctionReason'-'idempotencyKey';vehicle_key:=neuvetra.m67_hash(jsonb_build_array(a#>>'{vehicle,assetId}','Fossil Diesel','2025'));select * into head from neuvetra.mobile_diesel_heads where company_id=target_company and id=target_worksheet for update;
if target_worksheet is null then if request->'expectedVersionId'<>'null' or exists(select 1 from neuvetra.mobile_diesel_heads where company_id=target_company and source_id=(a#>>'{binding,sourceId}')::uuid) then raise exception 'source stream exists' using errcode='23505';end if;if(select count(*) from neuvetra.mobile_diesel_heads where company_id=target_company)>=3 then raise exception 'stream limit' using errcode='54000';end if;insert into neuvetra.mobile_diesel_heads(id,company_id,source_id,asset_id,vehicle_key)values(gen_random_uuid(),target_company,(a#>>'{binding,sourceId}')::uuid,a#>>'{vehicle,assetId}',vehicle_key)returning * into head;
else if head.id is null or head.source_id::text<>a#>>'{binding,sourceId}' or head.asset_id<>a#>>'{vehicle,assetId}' or head.vehicle_key<>vehicle_key then raise exception 'immutable vehicle identity conflict' using errcode='23505';end if;select * into prior from neuvetra.mobile_diesel_versions where company_id=target_company and id=head.version_id;if prior.id::text is distinct from request->>'expectedVersionId' or prior.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'stale source version' using errcode='23505';end if;if prior.payload->'activity'=a then raise exception 'no-op correction' using errcode='23505';end if;end if;
if(select count(*) from neuvetra.mobile_diesel_versions where company_id=target_company)>=40 then raise exception 'version limit' using errcode='54000';end if;
if a->'fuelStatement'<>'null' then fuel_id:=gen_random_uuid();fuel_text:=neuvetra.m74_statement(a,coverage,'fuel');fuel_hash:=encode(sha256(convert_to(fuel_text,'utf8')),'hex');fuel_statement:=jsonb_build_object('id',fuel_id,'profile','m74-synthetic-fuel-statement-v1','input',a->'fuelStatement','locator','m74-fuel-statement:'||fuel_id::text||':annual-activity','text',fuel_text,'sha256',fuel_hash,'byteLength',octet_length(convert_to(fuel_text,'utf8')));fuel_key:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{fuelStatement,issuer}'),lower(a#>>'{fuelStatement,reference}'),'2025'));select * into reservation from neuvetra.mobile_diesel_evidence_reservations where company_id=target_company and evidence_key=fuel_key for update;if found and(reservation.worksheet_id<>head.id or reservation.statement_kind<>'fuel')then raise exception 'evidence identity conflict' using errcode='23505';elsif not found then insert into neuvetra.mobile_diesel_evidence_reservations values(target_company,fuel_key,head.id,'fuel',clock_timestamp());end if;end if;
if a->'mileageStatement'<>'null' then mileage_id:=gen_random_uuid();mileage_text:=neuvetra.m74_statement(a,coverage,'mileage');mileage_hash:=encode(sha256(convert_to(mileage_text,'utf8')),'hex');mileage_statement:=jsonb_build_object('id',mileage_id,'profile','m74-synthetic-mileage-statement-v1','input',a->'mileageStatement','locator','m74-mileage-statement:'||mileage_id::text||':annual-activity','text',mileage_text,'sha256',mileage_hash,'byteLength',octet_length(convert_to(mileage_text,'utf8')));mileage_key:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{mileageStatement,issuer}'),lower(a#>>'{mileageStatement,reference}'),'2025'));select * into reservation from neuvetra.mobile_diesel_evidence_reservations where company_id=target_company and evidence_key=mileage_key for update;if found and(reservation.worksheet_id<>head.id or reservation.statement_kind<>'mileage')then raise exception 'evidence identity conflict' using errcode='23505';elsif not found then insert into neuvetra.mobile_diesel_evidence_reservations values(target_company,mileage_key,head.id,'mileage',clock_timestamp());end if;end if;
expected_calc:=neuvetra.m74_calculation(a,fuel_hash,mileage_hash);if calculation is distinct from expected_calc then raise exception 'calculation binding invalid' using errcode='22023';end if;update neuvetra.mobile_diesel_heads set fuel_reference_key=fuel_key,mileage_reference_key=mileage_key where id=head.id;captured:=date_trunc('milliseconds',clock_timestamp());
select jsonb_agg(x order by x collate "C") into contributors from(select distinct x from(select jsonb_array_elements_text(coalesce(prior.payload->'contributorIds','[]'))x union all select jsonb_array_elements_text(coverage->'contributorIds') union all select actor::text)a)a;input_hash:=neuvetra.m67_hash(a);body:=jsonb_build_object('activity',a,'activityStatus',neuvetra.m74_activity_status(a),'coverageVersion',coverage,'fuelStatement',fuel_statement,'mileageStatement',mileage_statement,'calculation',calculation,'findings',neuvetra.m74_findings(a));content_hash:=neuvetra.m67_hash(body);
v:=jsonb_build_object('profile','synthetic-mobile-diesel-v1','id',new_id,'companyId',target_company,'worksheetId',head.id,'version',head.revision+1,'previousVersionId',prior.id,'previousVersionSha256',prior.version_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'contributorIds',contributors,'correctionReason',request->'correctionReason','inputSha256',input_hash,'contentSha256',content_hash);version_hash:=neuvetra.m67_hash(v);v:=(v-'profile')||body||jsonb_build_object('versionSha256',version_hash,'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','review',null);frozen:=neuvetra.m67_canonical(v);
if octet_length(convert_to(frozen,'utf8'))>102400 then raise exception 'version bytes limit' using errcode='54001';end if;perform neuvetra.m74_capacity(target_company,octet_length(convert_to(frozen,'utf8'))+4096);if fuel_id is not null then insert into neuvetra.mobile_diesel_fuel_statements values(fuel_id,target_company,fuel_statement,fuel_hash,fuel_text);end if;if mileage_id is not null then insert into neuvetra.mobile_diesel_mileage_statements values(mileage_id,target_company,mileage_statement,mileage_hash,mileage_text);end if;
insert into neuvetra.mobile_diesel_versions values(new_id,target_company,head.id,head.revision+1,prior.id,(a#>>'{binding,coverageVersionId}')::uuid,fuel_id,mileage_id,(a->>'quantityGallons')::numeric,(a->>'distanceMiles')::numeric,v,input_hash,content_hash,version_hash,actor,captured,frozen);insert into neuvetra.mobile_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'save',fingerprint,new_id);insert into neuvetra.mobile_diesel_audit values(gen_random_uuid(),target_company,new_id,'save',version_hash,actor,captured);update neuvetra.mobile_diesel_heads set version_id=new_id,revision=revision+1 where id=head.id;return new_id;end $$;
create function neuvetra.review_mobile_diesel(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;old record;body jsonb;fingerprint text;digest text;new_id uuid:=gen_random_uuid();captured timestamptz;pair record;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.mobile_diesel_heads where company_id=target_company and id=target_worksheet for update;
perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,decision,note,acknowledgedLimitations,idempotencyKey');for pair in select key,value from jsonb_each(request) where key<>'acknowledgedLimitations'loop if jsonb_typeof(pair.value)<>'string' then raise exception 'invalid review type' using errcode='22023';end if;end loop;
if request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or request->>'decision' not in('accepted_bounded_internal','changes_requested') or request->'acknowledgedLimitations'<>'["synthetic_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","vehicle_mobile_combustion_subtotal_only","upstream_fuel_emissions_excluded","requirements_not_determined","no_external_assurance"]'::jsonb then raise exception 'invalid review' using errcode='22023';end if;perform neuvetra.m74_text(request->'note',500);
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.mobile_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'review' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
select * into v from neuvetra.mobile_diesel_versions where company_id=target_company and worksheet_id=target_worksheet and id=(request->>'versionId')::uuid;if not found or v.version_sha256<>request->>'expectedVersionSha256' or not exists(select 1 from neuvetra.mobile_diesel_heads where id=target_worksheet and version_id=v.id) then raise exception 'stale review version' using errcode='23505';end if;
if v.payload->'contributorIds'?actor::text then raise exception 'contributor cannot review' using errcode='42501';end if;perform neuvetra.m74_coverage(target_company,v.payload#>'{activity,binding}',true);if request->>'decision'='accepted_bounded_internal' and v.payload->'calculation'='null' then raise exception 'missing calculation' using errcode='22023';end if;
captured:=date_trunc('milliseconds',clock_timestamp());body:=jsonb_build_object('id',new_id,'versionId',v.id,'versionSha256',v.version_sha256,'decision',request->'decision','note',request->'note','acknowledgedLimitations',request->'acknowledgedLimitations','reviewerId',actor,'reviewedAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-mobile-diesel-v1','companyId',target_company));body:=body||jsonb_build_object('decisionSha256',digest);
insert into neuvetra.mobile_diesel_reviews values(new_id,target_company,v.id,body,digest,actor,captured);insert into neuvetra.mobile_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'review',fingerprint,new_id);insert into neuvetra.mobile_diesel_audit values(gen_random_uuid(),target_company,new_id,'review',digest,actor,captured);return new_id;end $$;

create function neuvetra.m74_escape(v text) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select replace(replace(replace(replace(replace(coalesce(v,'Missing'),'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;')$$;
create function neuvetra.m74_pair(label text,v text) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '<dt>'||label||'</dt><dd>'||neuvetra.m74_escape(v)||'</dd>'$$;
create function neuvetra.m74_render_report(snapshot jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare v jsonb:=snapshot->'version';c jsonb:=v->'calculation';m jsonb:=c->'method';src jsonb;f jsonb;entity jsonb;boundary jsonb;facts text;calc text;fuel text;mileage text;method text;findings text;begin
select x into src from jsonb_array_elements(v#>'{coverageVersion,snapshot,sources}')x where x->>'id'=v#>>'{activity,binding,sourceId}';select x into f from jsonb_array_elements(v#>'{coverageVersion,snapshot,facilities}')x where x->>'id'=v#>>'{activity,binding,facilityId}';select x into entity from jsonb_array_elements(v#>'{coverageVersion,snapshot,entities}')x where x->>'id'=v#>>'{activity,binding,entityId}';select x into boundary from jsonb_array_elements(v#>'{coverageVersion,snapshot,boundaryDecisions}')x where x->>'id'=v#>>'{activity,binding,boundaryDecisionId}';
facts:=neuvetra.m74_pair('Company',v#>>'{coverageVersion,snapshot,companyLabel}')||neuvetra.m74_pair('Entity',entity->>'legalName')||neuvetra.m74_pair('Boundary basis',boundary->>'reason')||neuvetra.m74_pair('Base facility',f->>'name')||neuvetra.m74_pair('Source',src->>'name')||neuvetra.m74_pair('Reporting period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('All-trip location basis','All vehicle travel, including interstate trips')||neuvetra.m74_pair('Coverage version',v#>>'{activity,binding,coverageVersionId}')||neuvetra.m74_pair('Source version',v->>'version')||neuvetra.m74_pair('Vehicle asset ID',v#>>'{activity,vehicle,assetId}')||neuvetra.m74_pair('Vehicle class',v#>>'{activity,vehicle,vehicleClass}')||neuvetra.m74_pair('Classification basis',v#>>'{activity,vehicle,classificationBasis}')||neuvetra.m74_pair('Model year',v#>>'{activity,vehicle,modelYear}')||neuvetra.m74_pair('Fuel',v#>>'{activity,vehicle,fuel}')||neuvetra.m74_pair('Control basis',v#>>'{activity,vehicle,controlBasis}')||neuvetra.m74_pair('Entered consumed fuel (U.S. gallons)',v#>>'{activity,quantityGallons}')||neuvetra.m74_pair('Fuel statement amount (U.S. gallons)',v#>>'{activity,fuelStatement,statedQuantityGallons}')||neuvetra.m74_pair('Fuel dimension status',v#>>'{activityStatus,fuel}')||neuvetra.m74_pair('Fuel discrepancy explanation',coalesce(v#>>'{activity,fuelDiscrepancyReason}','Not applicable'))||neuvetra.m74_pair('Entered distance (vehicle-miles)',v#>>'{activity,distanceMiles}')||neuvetra.m74_pair('Mileage statement amount (vehicle-miles)',v#>>'{activity,mileageStatement,statedDistanceMiles}')||neuvetra.m74_pair('Mileage dimension status',v#>>'{activityStatus,mileage}')||neuvetra.m74_pair('Mileage discrepancy explanation',coalesce(v#>>'{activity,mileageDiscrepancyReason}','Not applicable'))||neuvetra.m74_pair('No-operation/no-consumption explanation',coalesce(v#>>'{activity,zeroReason}','Not applicable'))||neuvetra.m74_pair('Exact vehicle mobile-combustion subtotal (kg CO2e)',c#>>'{total,unrounded}')||neuvetra.m74_pair('Displayed vehicle mobile-combustion subtotal (kg CO2e)',c#>>'{total,display}')||neuvetra.m74_pair('Review as captured',coalesce(snapshot#>>'{review,decision}','Unreviewed'))||neuvetra.m74_pair('Reviewer note',coalesce(snapshot#>>'{review,note}','Not yet reviewed'))||neuvetra.m74_pair('Review time',coalesce(snapshot#>>'{review,reviewedAt}','Not yet reviewed'))||neuvetra.m74_pair('Correction reason',coalesce(v->>'correctionReason','Not applicable'));
if c='null' then calc:='<p>Required compatible activity and evidence are incomplete or contradictory; no emissions total was calculated.</p>';method:=neuvetra.m74_pair('Method','No calculation was admitted; method remains a development candidate');else calc:='<table><thead><tr><th>Gas</th><th>Mass</th><th>kg CO2e</th></tr></thead><tbody>'||(select string_agg('<tr><th>'||label||'</th><td>'||neuvetra.m74_escape(c#>>array['gasResults',key,'mass'])||' '||neuvetra.m74_escape(c#>>array['gasResults',key,'massUnit'])||'</td><td>'||neuvetra.m74_escape(c#>>array['gasResults',key,'co2e'])||'</td></tr>','' order by ord)from(values('co2','CO2',1),('ch4','CH4',2),('n2o','N2O',3))gases(key,label,ord))||'</tbody></table><p>CO2 uses consumed U.S. gallons. CH4 and N2O use vehicle-miles. Only the displayed total is rounded to four decimal places, using half-even rounding. Gas values and the exact total retain full precision.</p>';method:=neuvetra.m74_pair('Method ID and version',(m->>'id')||' / '||(m->>'version'))||neuvetra.m74_pair('Source',m->>'sourceTitle')||neuvetra.m74_pair('Source edition','January 15, 2025')||neuvetra.m74_pair('Workbook SHA-256',m->>'sourceSha256')||neuvetra.m74_pair('Factor locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'factorCells')with ordinality x(value,ord)))||neuvetra.m74_pair('GWP locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'gwpCells')with ordinality x(value,ord)))||neuvetra.m74_pair('Note locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'noteCells')with ordinality x(value,ord)))||neuvetra.m74_pair('Factor normalization','Published displayed decimals corroborated by the EPA 2025 PDF; XLSX binary tails are not used')||neuvetra.m74_pair('CO2 factor',(m->>'co2KgPerGallon')||' kg CO2 per U.S. gallon')||neuvetra.m74_pair('CH4 factor',(m->>'ch4GramsPerMile')||' g CH4 per vehicle-mile')||neuvetra.m74_pair('N2O factor',(m->>'n2oGramsPerMile')||' g N2O per vehicle-mile')||neuvetra.m74_pair('GWP basis',(m->>'gwpAssessment')||'; CH4 '||(m->>'ch4Gwp')||', N2O '||(m->>'n2oGwp'))||neuvetra.m74_pair('Rights status',m->>'rights')||neuvetra.m74_pair('Method status',m->>'status');end if;
fuel:=case when v->'fuelStatement'='null' then neuvetra.m74_pair('Evidence','No supporting fuel statement retained') else neuvetra.m74_pair('Statement type','Synthetic human-entered fuel statement')||neuvetra.m74_pair('Issuer',v#>>'{activity,fuelStatement,issuer}')||neuvetra.m74_pair('Reference',v#>>'{activity,fuelStatement,reference}')||neuvetra.m74_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('Stated consumed fuel (U.S. gallons)',v#>>'{activity,fuelStatement,statedQuantityGallons}')||neuvetra.m74_pair('Description',v#>>'{activity,fuelStatement,description}')||neuvetra.m74_pair('Manual confirmation',v#>>'{activity,fuelManualConfirmation}')||neuvetra.m74_pair('Retained statement locator',v#>>'{fuelStatement,locator}')||neuvetra.m74_pair('Statement SHA-256',v#>>'{fuelStatement,sha256}')||neuvetra.m74_pair('Statement byte length',v#>>'{fuelStatement,byteLength}') end;
mileage:=case when v->'mileageStatement'='null' then neuvetra.m74_pair('Evidence','No supporting mileage statement retained') else neuvetra.m74_pair('Statement type','Synthetic human-entered mileage statement')||neuvetra.m74_pair('Issuer',v#>>'{activity,mileageStatement,issuer}')||neuvetra.m74_pair('Reference',v#>>'{activity,mileageStatement,reference}')||neuvetra.m74_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('Stated distance (vehicle-miles)',v#>>'{activity,mileageStatement,statedDistanceMiles}')||neuvetra.m74_pair('Description',v#>>'{activity,mileageStatement,description}')||neuvetra.m74_pair('Manual confirmation',v#>>'{activity,mileageManualConfirmation}')||neuvetra.m74_pair('Retained statement locator',v#>>'{mileageStatement,locator}')||neuvetra.m74_pair('Statement SHA-256',v#>>'{mileageStatement,sha256}')||neuvetra.m74_pair('Statement byte length',v#>>'{mileageStatement,byteLength}') end;
select coalesce(string_agg('<li>'||neuvetra.m74_escape(message)||'</li>','' order by ord),'')into findings from(select x->>'message' message,min(ord)ord from jsonb_array_elements((v->'findings')||(v#>'{coverageVersion,findings}'))with ordinality a(x,ord)group by x->>'message')deduplicated;
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic vehicle mobile-combustion source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Vehicle mobile-combustion subtotal — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source, vehicle and activity</h2><dl>'||facts||'</dl><h2>Gas results and calculation trace</h2>'||calc||'<h2>Supporting synthetic fuel statement</h2><dl>'||fuel||'</dl><h2>Supporting synthetic mileage statement</h2><dl>'||mileage||'</dl><h2>Method and provenance</h2><dl>'||method||'</dl><h2>Corporate coverage remains incomplete</h2><p>This report covers one bounded vehicle source. Other stationary, mobile, fugitive, process, facility and period sources remain unresolved or separately assessed. Combustion only; upstream fuel emissions are excluded.</p><ul>'||findings||'</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>'||neuvetra.m74_escape(neuvetra.m67_canonical(snapshot))||'</pre></details></body></html>';end $$;
create function neuvetra.create_mobile_diesel_report(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;decision record;old record;new_id uuid:=gen_random_uuid();captured timestamptz;fingerprint text;snapshot jsonb;snapshot_text text;html text;body jsonb;digest text;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.mobile_diesel_heads where company_id=target_company and id=target_worksheet for update;
perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDecisionId,expectedDecisionSha256,idempotencyKey');
if jsonb_typeof(request->'versionId')<>'string' or request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'idempotencyKey')<>'string' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedVersionSha256')<>'string' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' then raise exception 'invalid report request' using errcode='22023';end if;
if request->'expectedDecisionId'='null' then if request->'expectedDecisionSha256'<>'null' then raise exception 'invalid decision pair' using errcode='23505';end if;else if jsonb_typeof(request->'expectedDecisionId')<>'string' or request->>'expectedDecisionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedDecisionSha256')<>'string' or request->>'expectedDecisionSha256'!~'^[0-9a-f]{64}$' then raise exception 'invalid decision pair' using errcode='23505';end if;end if;
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','report','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.mobile_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'report' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
select * into v from neuvetra.mobile_diesel_versions where company_id=target_company and worksheet_id=target_worksheet and id=(request->>'versionId')::uuid;if not found or v.version_sha256<>request->>'expectedVersionSha256' then raise exception 'report version conflict' using errcode='23505';end if;perform neuvetra.m74_coverage(target_company,v.payload#>'{activity,binding}',true);
select * into decision from neuvetra.mobile_diesel_reviews where company_id=target_company and version_id=v.id;
if decision.id::text is distinct from request->>'expectedDecisionId' or decision.decision_sha256 is distinct from request->>'expectedDecisionSha256' then raise exception 'actual decision does not match report pin' using errcode='23505';end if;
snapshot:=jsonb_build_object('profile','m74-mobile-source-report-v1','version',v.payload,'review',decision.payload);snapshot_text:=neuvetra.m67_canonical(snapshot);html:=neuvetra.m74_render_report(snapshot);if octet_length(convert_to(html,'utf8'))>131072 then raise exception 'report bytes limit' using errcode='54001';end if;
captured:=date_trunc('milliseconds',clock_timestamp());body:=jsonb_build_object('id',new_id,'companyId',target_company,'worksheetId',target_worksheet,'versionId',v.id,'versionSha256',v.version_sha256,'decisionId',decision.id,'decisionSha256',decision.decision_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'rendererVersion','m74-mobile-source-report-v1','htmlSha256',encode(sha256(convert_to(html,'utf8')),'hex'),'htmlByteLength',octet_length(convert_to(html,'utf8')),'snapshotSha256',encode(sha256(convert_to(snapshot_text,'utf8')),'hex'));
digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-mobile-diesel-v1'));body:=body||jsonb_build_object('html',html,'snapshotJson',snapshot_text,'reportSha256',digest);perform neuvetra.m74_capacity(target_company,octet_length(convert_to(body::text,'utf8')));
insert into neuvetra.mobile_diesel_reports values(new_id,target_company,target_worksheet,v.id,decision.id,body,digest,actor,captured);insert into neuvetra.mobile_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'report',fingerprint,new_id);insert into neuvetra.mobile_diesel_audit values(gen_random_uuid(),target_company,new_id,'report',digest,actor,captured);return new_id;end $$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='neuvetra' and(p.proname like 'm74_%' or p.proname in('save_mobile_diesel','review_mobile_diesel','create_mobile_diesel_report'))loop execute 'revoke all on function '||f.signature||' from public,authenticated,neuvetra_runtime';if f.proname in('save_mobile_diesel','review_mobile_diesel','create_mobile_diesel_report')then execute 'grant execute on function '||f.signature||' to neuvetra_runtime';end if;end loop;end $$;
create function neuvetra.m74_lock(target_company uuid,writing boolean) returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing) then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;
revoke all on function neuvetra.m74_lock(uuid,boolean) from public,authenticated;grant execute on function neuvetra.m74_lock(uuid,boolean) to neuvetra_runtime;
